  ];

  for (const [V, edges, want] of tests) {
    const got = highestAverageElevationGain(V, edges);
    if (!(Math.abs(got - want) < 1e-6)) {
      throw new Error(
        `\nhighestAverageElevationGain(${V}, ${JSON.stringify(edges)}): got: ${got}, want: ${want}\n`,
