class RunTests {
  public void runTests() {
    TestCase[] tests = {
        // Example from the book
        new TestCase(
            4,
            List.of(
                new Edge(0, 1, 3),
                new Edge(1, 2, 2),
                new Edge(2, 3, 1),
                new Edge(3, 0, 2)),
            2.0),

        // Single edge
        new TestCase(
            2,
            List.of(new Edge(0, 1, 5)),
            5.0),

        // No edges
        new TestCase(
            3,
            List.of(),
            0.0),

        // Multiple components
        new TestCase(
            6,
            List.of(
                new Edge(0, 1, 1),
                new Edge(1, 2, 2),
                new Edge(3, 4, 3),
                new Edge(4, 5, 5)),
            4.0),

        // Single node component
        new TestCase(
            3,
            List.of(new Edge(0, 1, 2)),
            2.0)
    };

    HighestAverageElevationGain solution = new HighestAverageElevationGain();
    for (TestCase test : tests) {
      double got = solution.solve(test.V(), test.edges());
      if (Math.abs(got - test.want()) >= 1e-6) {
        throw new RuntimeException(String.format(
            "\nsolve(%d, %s): got: %f, want: %f\n",
            test.V(), test.edges(), got, test.want()));
      }
    }
  }
}

public class Solution {
  public static void main(String[] args) {
    new RunTests().runTests();
  }
}
